import java.util.LinkedHashMap;
import java.util.Map;

public final class Cache {
    private static final class Entry {
        int value;
        long storedAt;

        Entry(int value, long storedAt) {
            this.value = value;
            this.storedAt = storedAt;
        }
    }

    private final int capacity;
    private final long ttl;
    private final LinkedHashMap<String, Entry> store;

    public Cache(int capacity, long ttl) {
        this.capacity = capacity;
        this.ttl = ttl;
        this.store = new LinkedHashMap<>(16, 0.75f, true);
    }

    public void put(String key, int value, long now) {
        store.remove(key);
        if (store.size() >= capacity) {
            String oldest = store.keySet().iterator().next();
            store.remove(oldest);
        }
        store.put(key, new Entry(value, now));
    }

    public Integer get(String key, long now) {
        Entry e = store.get(key);
        if (e == null) {
            return null;
        }
        if (now - e.storedAt >= ttl) {
            store.remove(key);
            return null;
        }
        return e.value;
    }
}

