public final class CacheTest {
    public static void main(String[] args) {
        checkCapacityEvictsLRU();
        checkGetRefreshesRecency();
        checkTtlExpiryIndependentOfCapacity();
        System.out.println("all tests passed");
    }

    static void checkCapacityEvictsLRU() {
        Cache c = new Cache(2, 1000);
        c.put("a", 1, 0);
        c.put("b", 2, 1);
        c.get("a", 2);
        c.put("c", 3, 3);
        if (!Integer.valueOf(1).equals(c.get("a", 4))) throw new AssertionError("a should be 1");
        if (c.get("b", 4) != null) throw new AssertionError("b should be evicted");
        if (!Integer.valueOf(3).equals(c.get("c", 4))) throw new AssertionError("c should be 3");
    }

    static void checkGetRefreshesRecency() {
        Cache c = new Cache(2, 1000);
        c.put("a", 1, 0);
        c.put("b", 2, 1);
        c.get("a", 2);
        c.get("b", 3);
        c.put("c", 3, 4);
        if (c.get("a", 5) != null) throw new AssertionError("a should be evicted");
        if (!Integer.valueOf(2).equals(c.get("b", 5))) throw new AssertionError("b should be 2");
    }

    static void checkTtlExpiryIndependentOfCapacity() {
        Cache c = new Cache(5, 10);
        c.put("a", 1, 0);
        if (!Integer.valueOf(1).equals(c.get("a", 9))) throw new AssertionError("a should still be present at t=9");
        if (c.get("a", 10) != null) throw new AssertionError("a should be expired at t=10");
    }
}

